dashboard.definition:
{
	"visualizations": {
		"viz_Ic7MlT3j": {
			"type": "splunk.table",
			"options": {
				"columnFormat": {
					"_time": {
						"width": 146
					},
					"SystemTime": {
						"width": 142
					},
					"Computer": {
						"width": 151
					},
					"EventID": {
						"width": 78
					},
					"ModifyingApplication": {
						"width": 368
					},
					"ModifyingUser": {
						"width": 296
					},
					"RuleName": {
						"width": 239
					},
					"ApplicationPath": {
						"width": 249
					},
					"Active": {
						"data": "> table | seriesByName(\"Active\") | formatByType(ActiveColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"Active\") | matchValue(ActiveRowColorsEditorConfig)"
					},
					"action": {
						"data": "> table | seriesByName(\"action\") | formatByType(actionColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"action\") | pick(actionRowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"action\") | matchValue(actionRowBackgroundColorsEditorConfig)",
						"width": 104
					},
					"status": {
						"data": "> table | seriesByName(\"status\") | formatByType(statusColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"status\") | pick(statusRowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusRowBackgroundColorsEditorConfig)"
					},
					"Direction": {
						"width": 101,
						"data": "> table | seriesByName(\"Direction\") | formatByType(DirectionColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"Direction\") | pick(DirectionRowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"Direction\") | matchValue(DirectionRowBackgroundColorsEditorConfig)"
					},
					"Description": {
						"width": 332
					},
					"LocalAddresses": {
						"width": 102
					},
					"SettingType": {
						"width": 130
					},
					"result": {
						"data": "> table | seriesByName(\"result\") | formatByType(resultColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName('result') | pick(resultRowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"result\") | matchValue(resultRowBackgroundColorsEditorConfig)",
						"width": 102
					},
					"RemoteAddresses": {
						"width": 118
					}
				},
				"count": 16
			},
			"dataSources": {
				"primary": "ds_NvmJe7ax"
			},
			"context": {
				"ActiveColumnFormatEditorConfig": {
					"number": {
						"thousandSeparated": false,
						"unitPosition": "after"
					}
				},
				"ActiveRowColorsEditorConfig": [
					{
						"match": "",
						"value": "#555555"
					}
				],
				"actionColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"actionRowColorsEditorConfig": [
					"#000000"
				],
				"actionRowBackgroundColorsEditorConfig": [
					{
						"match": "Allow",
						"value": "#d41f1f"
					},
					{
						"match": "added:block",
						"value": "#669922"
					},
					{
						"match": "added:allow",
						"value": "#d41f1f"
					},
					{
						"match": "deleted",
						"value": "#cba700"
					},
					{
						"match": "modified:allow",
						"value": "#d41f1f"
					},
					{
						"match": "modified:block",
						"value": "#669922"
					},
					{
						"match": "Block",
						"value": "#669922"
					}
				],
				"statusColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"statusRowColorsEditorConfig": [
					"#000000"
				],
				"statusRowBackgroundColorsEditorConfig": [
					{
						"match": "active",
						"value": "#b6c75a"
					},
					{
						"match": "inactive",
						"value": "#d94e17"
					}
				],
				"DirectionColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"DirectionRowColorsEditorConfig": [
					"#000000"
				],
				"DirectionRowBackgroundColorsEditorConfig": [
					{
						"match": "N/A",
						"value": "#555555"
					}
				],
				"resultColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"resultRowColorsEditorConfig": [
					"#3c444d"
				],
				"resultRowBackgroundColorsEditorConfig": [
					{
						"match": "added:allow",
						"value": "#d94e17"
					},
					{
						"match": "added:block",
						"value": "#b6c75a"
					},
					{
						"match": "deleted",
						"value": "#f8be44"
					},
					{
						"match": "modified:allow",
						"value": "#d94e17"
					},
					{
						"match": "modified:block",
						"value": "#b6c75a"
					}
				]
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"type": "auto",
						"newTab": true
					}
				}
			],
			"hideWhenNoData": true
		},
