			}
		}
	},
	"dataSources": {
		"ds_2ATy9dLL": {
			"type": "ds.search",
			"options": {
				"query": "index IN `windows_firewall_index` source=\"*WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall\" NOT EventID=\"2010\" \n| lookup windows_firewall_event_id EventID OUTPUT Description AS Description1 \n| lookup windows_firewall_event_id EventID, SettingType OUTPUT Description AS Description2, SettingName \n| eval Description = case(isnotnull(SettingType), Description2 . \" --> \" . SettingName, true(), Description1) \n| fields _time Computer EventID Description \n    ModifyingApplication ModifyingUser RuleName result status ApplicationPath direction Protocol LocalAddresses LocalPorts RemoteAddresses RemotePorts change_type \n| search Computer IN ($ms_computer$) EventID IN ($ms_eventid$) change_type IN ($ms_change_type$)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "ds_basesearch"
		},
		"ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| rare limit=3 EventID by Computer \n| eval ratio = count+\"/\"+_tc | sort + count\n| fields - _tc percent count\n"
			},
			"name": "Search_2"
		},
		"ds_VnZLcS08_ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| search EventID IN (2082,2083,2003) status != \"N/A\" \n| stats latest(_time) as change_time by Computer status\n| eval change_time = strftime(change_time, \"%Y-%m-%d %H:%M:%S %Z\") \n| sort -change_time"
			},
			"name": "Search_3"
		},
		"ds_3eS7o5bS_ds_VnZLcS08_ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| search Description=\"*rule*\" | timechart count(EventID) by result"
			},
			"name": "Search_4"
		},
		"ds_QKXx99KS_ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| rare limit=5 ModifyingApplication \n| eval ratio = count+\"/\"+_tc | sort + count\n| fields - _tc percent count\n"
			},
			"name": "Search_6"
		},
		"ds_R9CxM7aW_ds_QKXx99KS_ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| rare limit=5 LocalPorts \n| eval ratio = count+\"/\"+_tc | sort + count\n| fields - _tc percent count\n"
			},
			"name": "Search_7"
		},
		"ds_inHrKFw3_ds_R9CxM7aW_ds_QKXx99KS_ds_BKLBNLzy": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| rare limit=5 RemotePorts \n| eval ratio = count+\"/\"+_tc | sort + count\n| fields - _tc percent count\n"
			},
			"name": "Search_8"
		},
		"ds_kAa8dMuq": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| stats values(EventID) by Computer"
			},
			"name": "Computers_List"
		},
		"ds_iMst48Rh": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| stats values(EventID) by Description"
			},
			"name": "Changes List"
		},
		"ds_F0ygtX88": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| stats values(EventID) by change_type"
			},
			"name": "Change Type List"
		},
		"ds_NvmJe7ax": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_2ATy9dLL",
				"query": "| table _time Computer EventID Description \n    ModifyingApplication ModifyingUser RuleName result status ApplicationPath direction Protocol LocalAddresses LocalPorts RemoteAddresses RemotePorts \n| sort - _time"
			},
			"name": "Change History"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					},
					"refresh": "15m",
					"refreshType": "delay"
				}
			}
		}
	},
	"inputs": {
		"input_global_trp": {
			"type": "input.timerange",
			"options": {
				"token": "global_time",
				"defaultValue": "-24h@h,now"
			},
			"title": "Période globale"
		},
		"input_MaJWTH17": {
			"options": {
				"items": ">frame(label, value) | prepend(formattedStatics) | objects()",
				"defaultValue": [
					"*"
				],
				"token": "ms_computer"
			},
			"title": "Computer",
			"type": "input.multiselect",
			"dataSources": {
				"primary": "ds_kAa8dMuq"
			},
			"context": {
				"formattedConfig": {
					"number": {
						"prefix": ""
					}
				},
				"formattedStatics": ">statics | formatByType(formattedConfig)",
				"statics": [
					[
						"Tout"
					],
					[
						"*"
					]
				],
				"label": ">primary | seriesByName(\"Computer\") | renameSeries(\"label\") | formatByType(formattedConfig)",
				"value": ">primary | seriesByName(\"Computer\") | renameSeries(\"value\") | formatByType(formattedConfig)"
			}
		},
